      "sourceBinding": "[\"第71课 · He’s awful!\",[\"What's Ron Marston like, Pauline?\",\"He’s awful! He telephoned me four times yesterday, and three times the day before yesterday.\",\"He telephoned the office yesterday morning and yesterday afternoon. My boss answered the telephone.\",\"What did your boss say to him?\",\"He said, ‘Pauline is typing letters. She can’t speak to you now!’\",\"Then I arrived home at six o'clock yesterday evening. He telephoned again. But I didn’t answer the phone!\",\"Did he telephone again last night?\",\"Yes, he did. He telephoned at nine o’clock.\",\"What did you say to him?\",\"I said, ‘This is Pauline’s mother. Please don’t telephone my daughter again!’\",\"Did he telephone again?\",\"No, he didn’t!\"]]",
