      "id": "nce-b1-4be758-l113",
      "book": 1,
      "number": 113,
      "sourceBinding": "[\"第113课 · Small change\",[\"Fares, please!\",\"Trafalgar Square, please.\",\"I'm sorry, sir. I can’t change a ten-pound note. Haven't you got any small change?\",\"I’ve got no small change, I'm afraid.\",\"I'll ask some of the passengers.\",\"Have you any small change, sir?\",\"I'm sorry. I’ve got none.\",\"I haven't got any either.\",\"Can you change this ten-pound note, madam?\",\"I'm afraid I can’t.\",\"Neither can I.\",\"I’m very sorry, sir. You must get off the bus. None of our passengers can change this note. They're all millionaires!\",\"Except us.\",\"I've got some small change.\",\"So have I.\"]]",
      "sourceBindingSha256": "7967789448a6dc731eba46ff26f7771ff6b6619f4dcb4dba992892c43dbb2a18",
