          "meaning": "最低的（low 的最高级）",
          "pos": "adj.",
          "sourceSentence": "Modern industry is based on the conception of the maximum production at lowest cost, in order that an individual or a group of individuals may earn as much money as possible.",
          "sourceLocation": "body",
