      "id": "nce-b2-eef57c-l089",
      "book": 2,
      "number": 89,
      "sourceBinding": "[\"第89课 · A slip of the tongue\",[\"People will do anything to see a free show — even if it is a bad one. When the news got round that a comedy show would be presented at our local cinema by the P. and U. Bird Seed Company, we all rushed to see it. We had to queue for hours to get in and there must have been several hundred people present just before the show began. Unfortunately, the show was one of the dullest we have ever seen. Those who failed to get in need not have felt disappointed, as many of the artistes who should have appeared did not come. The only funny things we heard that evening came from the advertiser at the beginning of the programme. He was obviously very nervous and for some minutes stood awkwardly before the microphone. As soon as he opened his mouth, everyone burst out laughing. We all know what the poor man should have said, but what he actually said was: ‘This is the Poo and Ee Seed Bird Company. Good ladies, evening and gentlemen!’\"]]",
      "sourceBindingSha256": "cf5ba3335a8df75a635676c7e5522e6bc8a818524c6ffa76efbc36d921b938ed",
